/**
 * The SRD 5.1 spell list.
 *
 * Written as compact tuples rather than objects: at three hundred-odd spells,
 * the tuple form is far easier to scan, diff, and correct than the same data
 * spread over ten thousand lines of JSON.
 *
 * Tuple order: name, level, school, classes, casting time, range, components,
 * duration, effect. Classes use single letters:
 *   b bard · c cleric · d druid · p paladin · r ranger · s sorcerer
 *   k warlock · w wizard
 */

type SpellTuple = [
  name: string,
  level: number,
  school: string,
  classes: string,
  time: string,
  range: string,
  components: string,
  duration: string,
  text: string,
]

