function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/[’']/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
}

const entries: Entry[] = spells.map(([name, level, school, classes, time, range, components, duration, text]) => {
  const classList = classes.split('').map((letter) => CLASS_BY_LETTER[letter]).filter((value): value is string => !!value)
  const schoolName = SCHOOLS[school] ?? school
  const concentration = duration.startsWith('Concentration')

  return {
    id: slugify(name),
    name,
    summary: text,
    icon: level === 0 ? '✨' : undefined,
    tags: [...classList, `level-${level}`, schoolName.toLowerCase(), ...(concentration ? ['concentration'] : [])],
    meta: {
      level,
      School: schoolName,
      'Casting Time': time,
      Range: range,
      Components: components,
      Duration: duration,
    },
  }
})

export const spellCollection: Collection = {
  id: 'spells',
  label: 'Spells',
  singular: 'Spell',
  entries,
}

/** Human-readable label for a spell level, used by the UI and the PDF. */
export function spellLevelLabel(level: number): string {
  if (level === 0) return 'Cantrip'
  const suffix = level === 1 ? 'st' : level === 2 ? 'nd' : level === 3 ? 'rd' : 'th'
  return `${level}${suffix} level`
}
